 22	import com.google.common.annotations.GwtCompatible;
 23	import com.google.common.base.Function;
 24	import com.google.errorprone.annotations.ForOverride;
 25	import com.google.errorprone.annotations.concurrent.LazyInit;
 26	import com.google.j2objc.annotations.RetainedLocalRef;
 27	import java.util.concurrent.CancellationException;
 28	import java.util.concurrent.ExecutionException;
 29	import java.util.concurrent.Executor;
 30	import org.jspecify.annotations.Nullable;
 31	
 32	/** Implementations of {@code Futures.transform*}. */
 33	@GwtCompatible
 34	// Whenever both tests are cheap and functional, it's faster to use &, | instead of &&, ||
 35	@SuppressWarnings("ShortCircuitBoolean")
 36	abstract class AbstractTransformFuture<
 37	        I extends @Nullable Object, O extends @Nullable Object, F, T extends @Nullable Object>
 38	    extends FluentFuture.TrustedFuture<O> implements Runnable {
 39	  static <I extends @Nullable Object, O extends @Nullable Object> ListenableFuture<O> createAsync(
 40	      ListenableFuture<I> input,
 41	      AsyncFunction<? super I, ? extends O> function,
 42	      Executor executor) {
 43	    AsyncTransformFuture<I, O> output = new AsyncTransformFuture<>(input, function);
 44	    input.addListener(output, rejectionPropagatingExecutor(executor, output));
 45	    return output;
 46	  }
 47	
 48	  static <I extends @Nullable Object, O extends @Nullable Object> ListenableFuture<O> create(
 49	      ListenableFuture<I> input, Function<? super I, ? extends O> function, Executor executor) {
 50	    TransformFuture<I, O> output = new TransformFuture<>(input, function);
 51	    input.addListener(output, rejectionPropagatingExecutor(executor, output));
 52	    return output;
 53	  }
 54	
 55	  /*
 56	   * In certain circumstances, this field might theoretically not be visible to an afterDone() call
 57	   * triggered by cancel(). For details, see the comments on the fields of TimeoutFuture.
 58	   */
 59	  @LazyInit @Nullable ListenableFuture<? extends I> inputFuture;
 60	  @LazyInit @Nullable F function;
 61	
 62	  AbstractTransformFuture(ListenableFuture<? extends I> inputFuture, F function) {
 63	    this.inputFuture = checkNotNull(inputFuture);
 64	    this.function = checkNotNull(function);
 65	  }
 66	
 67	  @Override
 68	  @SuppressWarnings({
 69	    "CatchingUnchecked", // sneaky checked exception
 70	    "nullness", // TODO(b/147136275): Remove once our checker understands & and |.
 71	  })
 72	  public final void run() {
 73	    @RetainedLocalRef ListenableFuture<? extends I> localInputFuture = inputFuture;
 74	    @RetainedLocalRef F localFunction = function;
 75	    if (isCancelled() | localInputFuture == null | localFunction == null) {
 76	      return;
 77	    }
 78	    inputFuture = null;
 79	
 80	    if (localInputFuture.isCancelled()) {
 81	      @SuppressWarnings("unchecked")
 82	      boolean unused =
 83	          setFuture((ListenableFuture<O>) localInputFuture); // Respects cancellation cause setting
 84	      return;
 85	    }
 86	
 87	    /*
 88	     * Any of the setException() calls below can fail if the output Future is cancelled between now
 89	     * and then. This means that we're silently swallowing an exception -- maybe even an Error. But
 90	     * this is no worse than what FutureTask does in that situation. Additionally, because the
 91	     * Future was cancelled, its listeners have been run, so its consumers will not hang.
 92	     *
 93	     * Contrast this to the situation we have if setResult() throws, a situation described below.
 94	     */
 95	    I sourceResult;
 96	    try {
 97	      sourceResult = getDone(localInputFuture);
 98	    } catch (CancellationException e) {
 99	      // TODO(user): verify future behavior - unify logic with getFutureValue in AbstractFuture. This
100	      // code should be unreachable with correctly implemented Futures.
101	      // Cancel this future and return.
102	      // At this point, inputFuture is cancelled and outputFuture doesn't exist, so the value of
103	      // mayInterruptIfRunning is irrelevant.
104	      cancel(false);
105	      return;
106	    } catch (ExecutionException e) {
107	      // Set the cause of the exception as this future's exception.
108	      setException(e.getCause());
109	      return;
110	    } catch (Exception e) { // sneaky checked exception
111	      // Bug in inputFuture.get(). Propagate to the output Future so that its consumers don't hang.
112	      setException(e);
113	      return;
114	    } catch (Error e) {
115	      /*
116	       * StackOverflowError, OutOfMemoryError (e.g., from allocating ExecutionException), or
117	       * something. Try to treat it like a RuntimeException. If we overflow the stack again, the
118	       * resulting Error will propagate upward up to the root call to set().
119	       */
120	      setException(e);
121	      return;
122	    }
123	
124	    T transformResult;
125	    try {
126	      transformResult = doTransform(localFunction, sourceResult);
127	    } catch (Throwable t) {
128	      restoreInterruptIfIsInterruptedException(t);
129	      // This exception is irrelevant in this thread, but useful for the client.
130	      setException(t);
131	      return;
132	    } finally {
133	      function = null;
134	    }
135	
136	    /*
137	     * If set()/setValue() throws an Error, we let it propagate. Why? The most likely Error is a
138	     * StackOverflowError (from deep transform(..., directExecutor()) nesting), and calling
139	     * setException(stackOverflowError) would fail:
140	     *
141	     * - If the stack overflowed before set()/setValue() could even store the result in the output
142	     * Future, then a call setException() would likely also overflow.
143	     *
144	     * - If the stack overflowed after set()/setValue() stored its result, then a call to
145	     * setException() will be a no-op because the Future is already done.
146	     *
147	     * Both scenarios are bad: The output Future might never complete, or, if it does complete, it
148	     * might not run some of its listeners. The likely result is that the app will hang. (And of
149	     * course stack overflows are bad news in general. For example, we may have overflowed in the
150	     * middle of defining a class. If so, that class will never be loadable in this process.) The
151	     * best we can do (since logging may overflow the stack) is to let the error propagate. Because
152	     * it is an Error, it won't be caught and logged by AbstractFuture.executeListener. Instead, it
153	     * can propagate through many layers of AbstractTransformFuture up to the root call to set().
154	     *
155	     * https://github.com/google/guava/issues/2254
156	     *
157	     * Other kinds of Errors are possible:
158	     *
159	     * - OutOfMemoryError from allocations in setFuture(): The calculus here is similar to
160	     * StackOverflowError: We can't reliably call setException(error).
161	     *
162	     * - Any kind of Error from a listener. Even if we could distinguish that case (by exposing some
163	     * extra state from AbstractFuture), our options are limited: A call to setException() would be
164	     * a no-op. We could log, but if that's what we really want, we should modify
165	     * AbstractFuture.executeListener to do so, since that method would have the ability to continue
166	     * to execute other listeners.
167	     *
168	     * What about RuntimeException? If there is a bug in set()/setValue() that produces one, it will
169	     * propagate, too, but only as far as AbstractFuture.executeListener, which will catch and log
170	     * it.
171	     */
172	    setResult(transformResult);
173	  }
