175	  /** Template method for subtypes to actually run the transform. */
176	  @ForOverride
177	  @ParametricNullness
178	  abstract T doTransform(F function, @ParametricNullness I result) throws Exception;
179	
180	  /** Template method for subtypes to actually set the result. */
181	  @ForOverride
182	  abstract void setResult(@ParametricNullness T result);
183	
184	  @Override
185	  protected final void afterDone() {
186	    @RetainedLocalRef ListenableFuture<? extends I> localInputFuture = inputFuture;
187	    maybePropagateCancellationTo(localInputFuture);
188	    this.inputFuture = null;
189	    this.function = null;
190	  }
191	
192	  @Override
193	  protected @Nullable String pendingToString() {
194	    @RetainedLocalRef ListenableFuture<? extends I> localInputFuture = inputFuture;
195	    @RetainedLocalRef F localFunction = function;
196	    String superString = super.pendingToString();
197	    String resultString = "";
198	    if (localInputFuture != null) {
199	      resultString = "inputFuture=[" + localInputFuture + "], ";
200	    }
201	    if (localFunction != null) {
202	      return resultString + "function=[" + localFunction + "]";
203	    } else if (superString != null) {
204	      return resultString + superString;
205	    }
206	    return null;
207	  }
208	
209	  /**
210	   * An {@link AbstractTransformFuture} that delegates to an {@link AsyncFunction} and {@link
211	   * #setFuture(ListenableFuture)}.
212	   */
213	  private static final class AsyncTransformFuture<
214	          I extends @Nullable Object, O extends @Nullable Object>
215	      extends AbstractTransformFuture<
216	          I, O, AsyncFunction<? super I, ? extends O>, ListenableFuture<? extends O>> {
217	    AsyncTransformFuture(
218	        ListenableFuture<? extends I> inputFuture, AsyncFunction<? super I, ? extends O> function) {
219	      super(inputFuture, function);
220	    }
221	
222	    @Override
223	    ListenableFuture<? extends O> doTransform(
224	        AsyncFunction<? super I, ? extends O> function, @ParametricNullness I input)
225	        throws Exception {
226	      ListenableFuture<? extends O> output = function.apply(input);
227	      checkNotNull(
228	          output,
229	          "AsyncFunction.apply returned null instead of a Future. "
230	              + "Did you mean to return immediateFuture(null)? %s",
231	          function);
232	      return output;
233	    }
234	
235	    @Override
236	    void setResult(ListenableFuture<? extends O> result) {
237	      setFuture(result);
238	    }
239	  }
240	
241	  /**
242	   * An {@link AbstractTransformFuture} that delegates to a {@link Function} and {@link
243	   * #set(Object)}.
244	   */
245	  private static final class TransformFuture<I extends @Nullable Object, O extends @Nullable Object>
246	      extends AbstractTransformFuture<I, O, Function<? super I, ? extends O>, O> {
247	    TransformFuture(
248	        ListenableFuture<? extends I> inputFuture, Function<? super I, ? extends O> function) {
249	      super(inputFuture, function);
250	    }
251	
252	    @Override
253	    @ParametricNullness
254	    O doTransform(Function<? super I, ? extends O> function, @ParametricNullness I input) {
255	      return function.apply(input);
256	    }
257	
258	    @Override
259	    void setResult(@ParametricNullness O result) {
260	      set(result);
261	    }
262	  }
263	}

